def discount(price: float, rate: float) -> float:
    return price * (1 - rate)
print(f'Total: {discount(100, 0.1):.2f}')

def normalize(name: str) -> str: return name.strip().title()
def make_label(name: str) -> str: return f'Customer: {normalize(name)}'
print(make_label('  asha '))
